+/** One row of the health checklist: a title, a status tag, detail, and its verb. */
+function HealthItem({
+  id,
+  title,
+  tag,
+  detail,
+  action,
+}: {
+  id?: string;
+  title: string;
+  tag: { color: string; label: string };
+  detail: ReactNode;
